define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_51.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e194132","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_52.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e194236","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_49.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e194340","topics":[]},{"title":"Doing the gradient amplifier and gradient power supply resistance checks","shortdesc":"<p class=\"shortdesc\">This topic provides information about doing resistance checks to diagnose short-circuit conditions and prevent gradient amplifier (RGA) and gradient power supply (RPS) damage.<\/p>","href":"t_DoingGradientAmplifierAndPSResistanceChecks_2.html","attributes":{"data-id":"id_2042835"},"menu":{"hasChildren":false},"tocID":"id_2042835-d46e194444","topics":[]},{"title":"Removing the Gradient Amplifier (RGA)","shortdesc":"<p class=\"shortdesc\">This procedure details the correct way to use a hoist kit to remove the gradient amplifier unit safely.<\/p>","href":"t_RemovingtheGradientAmplifierRGA.html","attributes":{"data-id":"id_2001533"},"menu":{"hasChildren":false},"tocID":"id_2001533-d46e194652","topics":[]},{"title":"Draining coolant from Gradient Amplifier (RGA)","shortdesc":"<p class=\"shortdesc\">Use this procedure to drain coolant from the RGA.<\/p>","href":"t_DrainingCoolantFromGradientAmplifierRGA.html","attributes":{"data-id":"id_2004398"},"menu":{"hasChildren":false},"tocID":"id_2004398-d46e194756","topics":[]},{"title":"Installing the Gradient Amplifier (RGA)","shortdesc":"<p class=\"shortdesc\">This procedure details the correct way to use a hoist kit to replace the gradient amplifier unit [Field Replaceable Unit (FRU)] safely.<\/p>","href":"t_InstallingTheGradientAmplifierRGA.html","attributes":{"data-id":"id_2003842"},"menu":{"hasChildren":false},"tocID":"id_2003842-d46e194860","topics":[]},{"title":"Removing the hoist","shortdesc":"<p class=\"shortdesc\">Remove the hoist beam and return it to its storage location.<\/p>","href":"t_RemovingTheHoist_8.html","attributes":{"data-id":"id_2003868"},"menu":{"hasChildren":false},"tocID":"id_2003868-d46e194964","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_51.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e195068","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_51.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e195173","topics":[]},{"title":"Refilling the Integrated Cooling Cabinet (ICC) coolant","shortdesc":"<p class=\"shortdesc\">Fill the Cabinet Cooling Unit (CCU) and Gradient Cooling Unit (GCU) tanks with coolant, as needed.<\/p>","href":"t_RefillingCoolant_6.html","attributes":{"data-id":"id_2002771"},"menu":{"hasChildren":false},"tocID":"id_2002771-d46e195277","topics":[]},{"title":"Calibrating Gradient DC Offset","shortdesc":"<p class=\"shortdesc\">Run the DC Offset Calibration tool.<\/p>","href":"t_CalibratingGradientDCOffset.html","attributes":{"data-id":"id_2004014"},"menu":{"hasChildren":false},"tocID":"id_2004014-d46e195381","topics":[]},{"title":"Doing DQA calibration","shortdesc":"<p class=\"shortdesc\">The DQA tool determines proper gradient polarity and proper gradient wiring by scanning a series of axial and coronal images of the DQA III phantom.<\/p>","href":"t_UsingtheDQAIICalibrationTool_3.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e195486","topics":[]},{"title":"Working with eddy current compensation tools","shortdesc":"<p class=\"shortdesc\">Use the appropriate eddy current compensation tool for your software version.<\/p>","href":"t_WorkingWithEddyCurrentCompTools_3.html","attributes":{"data-id":"id_2001480"},"menu":{"hasChildren":true},"tocID":"id_2001480-d46e195591","next":"id_2001480-d46e195591"},{"title":"Calibrating High Order Eddy Current (HOEC)","shortdesc":"<p class=\"shortdesc\">Use HOEC to characterize the time-dependent magnetic field errors in the bore up to at least the third order.<\/p>","href":"t_CalibratingHighOrderEddyCurrentHOEC_2.html","attributes":{"data-id":"id_2001481"},"menu":{"hasChildren":true},"tocID":"id_2001481-d46e196638","next":"id_2001481-d46e196638"},{"title":"Calibrating LVShim","shortdesc":"<p class=\"shortdesc\">The objective of the LVShim tool is to fine-tune magnet homogeneity.<\/p>","href":"t_CalibratingLVShim_2.html","attributes":{"data-id":"id_2002769"},"menu":{"hasChildren":true},"tocID":"id_2002769-d46e197154","next":"id_2002769-d46e197154"},{"title":"Doing the System Performance Test (SPT) ","shortdesc":"<p class=\"shortdesc\">The system performance test (SPT) automatically executes Eddy Current Check, SNR, Stability, and Coherent Noise tests. To do SPT in PM mode, you must launch SPT from the PM Assist menu.<\/p>","href":"t_SystemPerformanceTestSPTFullMode.html","attributes":{"data-id":"id_2003328"},"menu":{"hasChildren":true},"tocID":"id_2003328-d46e198000","next":"id_2003328-d46e198000"},{"title":"Running the Save and Restore tool","shortdesc":"<p class=\"shortdesc\">Use the <span class=\"keyword wintitle\">Guided Install<\/span> interface to save, verify, and restore system data.<\/p>","href":"t_RunningTheSaveandRestoreTool_2.html","attributes":{"data-id":"id_2000454"},"menu":{"hasChildren":true},"tocID":"id_2000454-d46e198314","next":"id_2000454-d46e198314"},{"title":"Doing a TPS reset","shortdesc":"<p class=\"shortdesc\">This document provides instructions for doing a TPS reset and examples of the results output.<span class=\"ph\"> If the system is not working properly, you can try a TPS reset to re-initialize the ISC chassis.<\/span><\/p>","href":"t_DoingTPSReset_3.html","attributes":{"data-id":"id_2001664"},"menu":{"hasChildren":false},"tocID":"id_2001664-d46e198733","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_78.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e198839","topics":[]}]});